     9	import useCurrentUserPersonalDetails from '@hooks/useCurrentUserPersonalDetails';
    10	import useLocalize from '@hooks/useLocalize';
    11	import useOnyx from '@hooks/useOnyx';
    12	import useThemeStyles from '@hooks/useThemeStyles';
    13	import useTransactionViolations from '@hooks/useTransactionViolations';
    14	import {dismissDuplicateTransactionViolation} from '@libs/actions/Transaction';
    15	import Navigation from '@libs/Navigation/Navigation';
    16	import type {PlatformStackRouteProp} from '@libs/Navigation/PlatformStackNavigation/types';
    17	import type {TransactionDuplicateNavigatorParamList} from '@libs/Navigation/types';
    18	import {getLinkedTransactionID, getReportAction} from '@libs/ReportActionsUtils';
    19	import {isReportIDApproved, isSettled} from '@libs/ReportUtils';
    20	import CONST from '@src/CONST';
    21	import ONYXKEYS from '@src/ONYXKEYS';
    22	import type SCREENS from '@src/SCREENS';
    23	import DuplicateTransactionsList from './DuplicateTransactionsList';
    24	
    25	function TransactionDuplicateReview() {
    26	    const styles = useThemeStyles();
    27	    const {translate} = useLocalize();
    28	    const route = useRoute<PlatformStackRouteProp<TransactionDuplicateNavigatorParamList, typeof SCREENS.TRANSACTION_DUPLICATE.REVIEW>>();
    29	    const currentPersonalDetails = useCurrentUserPersonalDetails();
    30	    const [report] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT}${route.params.threadReportID}`, {canBeMissing: true});
    31	    const reportAction = getReportAction(report?.parentReportID, report?.parentReportActionID);
    32	    const transactionID = getLinkedTransactionID(reportAction, report?.reportID) ?? undefined;
    33	    const transactionViolations = useTransactionViolations(transactionID);
    34	    const duplicateTransactionIDs = useMemo(
    35	        () => transactionViolations?.find((violation) => violation.name === CONST.VIOLATIONS.DUPLICATED_TRANSACTION)?.data?.duplicates ?? [],
    36	        [transactionViolations],
    37	    );
    38	    const transactionIDs = transactionID ? [transactionID, ...duplicateTransactionIDs] : duplicateTransactionIDs;
    39	
    40	    const [transactions] = useOnyx(
    41	        ONYXKEYS.COLLECTION.TRANSACTION,
    42	        {
    43	            selector: (allTransactions) =>
    44	                transactionIDs
    45	                    .map((id) => allTransactions?.[`${ONYXKEYS.COLLECTION.TRANSACTION}${id}`])
    46	                    .sort((a, b) => new Date(a?.created ?? '').getTime() - new Date(b?.created ?? '').getTime()),
    47	            canBeMissing: true,
    48	        },
    49	        [transactionIDs],
    50	    );
    51	
    52	    const keepAll = () => {
    53	        dismissDuplicateTransactionViolation(transactionIDs, currentPersonalDetails);
    54	        Navigation.goBack();
    55	    };
    56	
    57	    const hasSettledOrApprovedTransaction = transactions?.some((transaction) => isSettled(transaction?.reportID) || isReportIDApproved(transaction?.reportID));
    58	
    59	    return (
    60	        <ScreenWrapper testID={TransactionDuplicateReview.displayName}>
    61	            <FullPageNotFoundView shouldShow={!transactionID}>
    62	                <HeaderWithBackButton
    63	                    title={translate('iou.reviewDuplicates')}
    64	                    onBackButtonPress={() => Navigation.goBack(route.params.backTo)}
    65	                />
    66	                <View style={[styles.justifyContentCenter, styles.ph5, styles.pb3, styles.borderBottom]}>
    67	                    <Button
    68	                        text={translate('iou.keepAll')}
    69	                        onPress={keepAll}
    70	                    />
    71	                    {!!hasSettledOrApprovedTransaction && <Text style={[styles.textNormal, styles.colorMuted, styles.mt3]}>{translate('iou.someDuplicatesArePaid')}</Text>}
    72	                </View>
    73	                <DuplicateTransactionsList transactions={transactions ?? []} />
    74	            </FullPageNotFoundView>
    75	        </ScreenWrapper>
    76	    );
    77	}
    78	
    79	TransactionDuplicateReview.displayName = 'TransactionDuplicateReview';
    80	export default TransactionDuplicateReview;
